// Nodo "2. Extraer datos del mensaje" — adaptado específicamente al payload real de Whapi.Cloud.
//
// Formato confirmado en la documentación oficial de Whapi.Cloud (Incoming Webhooks > Incoming
// message / Groups): https://support.whapi.cloud/help-desk/receiving/webhooks/incoming-webhooks-format
//
// {
//   "messages": [{
//     "id": "...", "from_me": false, "type": "text", "chat_id": "1203xxxx@g.us",
//     "timestamp": 1713791337, "source": "mobile",
//     "text": { "body": "..." }, "from": "5491122334455", "from_name": "Juan"
//   }],
//   "event": { "type": "messages", "event": "post" },
//   "channel_id": "MANTIS-M72HC"
// }
//
// Corre en modo "Run Once for Each Item": devolver null descarta el item sin
// pasarlo al resto del workflow (así no llega a pegarle a Google Sheets por nada).

const body = $input.item.json.body || $input.item.json;
const msg = body.messages?.[0];

// Whapi también manda webhooks de otro tipo por la misma URL (acuses de recibo "statuses",
// eventos de canal, etc.) que no traen "messages". Los descartamos acá.
if (!msg) {
  return null;
}

// "from_me: true" es un eco de un mensaje que mandó el propio bot (ej. la confirmación
// "✅ Cargado: ..."). Sin este filtro el workflow terminaría reprocesando sus propias
// respuestas como si fueran gastos nuevos.
if (msg.from_me) {
  return null;
}

// Por ahora solo procesamos texto. Fotos de comprobantes quedan para una futura
// extensión con OCR (ver guía, sección "Próximos pasos posibles").
if (msg.type !== 'text') {
  return null;
}

const grupoId = msg.chat_id || '';
const remitente = msg.from_name || msg.from || 'Desconocido';
const texto = msg.text?.body || '';
const mensajeId = msg.id || '';
// Whapi manda el timestamp en segundos (epoch Unix, 10 dígitos).
const timestampRaw = msg.timestamp || Math.floor(Date.now() / 1000);
const fecha = new Date(Number(timestampRaw) * 1000);

return {
  json: {
    grupo_id: grupoId,
    remitente,
    mensaje_texto: texto,
    mensaje_id: mensajeId,
    fecha: fecha.toISOString().slice(0, 10),
    hora: fecha.toTimeString().slice(0, 5)
  }
};

// Parsea el texto del mensaje para extraer categoría, monto y descripción.
// Formato recomendado (el que promocionamos a los usuarios del grupo):
//   GASTO / Categoría / Monto / Descripción
//   Ejemplo: GASTO / Materiales / 45000 / Cemento y arena
// Si no viene en ese formato, intenta interpretarlo en texto libre.

const rawText = $json.mensaje_texto || '';

const categorias = {
  'Materiales': ['cemento','arena','ladrillo','hierro','caño','cano','cable','pintura','madera'],
  'Mano de Obra': ['jornal','oficial','ayudante','cuadrilla','contratista'],
  'Honorarios Profesionales': ['arquitecto','ingeniero','gestoria','gestoría','escribano','abogado'],
  'Servicios': ['luz','gas','agua','internet','seguro','alquiler equipo'],
  'Impuestos y Tasas': ['abl','ingresos brutos','tasa','municipalidad','monotributo'],
  'Equipamiento': ['herramienta','andamio','alquiler maquina','alquiler máquina','compra equipo'],
  'Varios': ['flete','comida obra','imprevisto','otros']
};

let categoria = null, monto = null, descripcion = null, estado = 'OK', motivo = '';

// No procesar si el mensaje está vacío o es un saludo/ruido conversacional
if (!rawText || rawText.trim().length < 3) {
  return { json: { ...$json, ignorar: true } };
}

const structured = rawText.match(/^\s*GASTO\s*\/\s*([^\/]+)\/\s*([\d.,]+)\s*\/\s*(.+)$/i);

if (structured) {
  categoria = structured[1].trim();
  monto = parseFloat(structured[2].replace(/\./g,'').replace(',','.'));
  descripcion = structured[3].trim();
  const catNames = Object.keys(categorias);
  const match = catNames.find(c => c.toLowerCase() === categoria.toLowerCase());
  if (!match) {
    estado = 'Revisar';
    motivo = `Categoría "${categoria}" no reconocida`;
  } else {
    categoria = match;
  }
} else {
  // Solo intenta interpretar texto libre si "parece" un gasto (contiene un número)
  const lower = rawText.toLowerCase();
  const tieneNumero = /\d/.test(lower);
  if (!tieneNumero) {
    return { json: { ...$json, ignorar: true } };
  }
  const montoMatch = lower.match(/(\d{1,3}(?:[.,]\d{3})+(?:[.,]\d+)?|\d+(?:[.,]\d+)?)\s*(mil|lucas|k)?/);
  if (montoMatch) {
    let num = parseFloat(montoMatch[1].replace(/\./g,'').replace(',','.'));
    if (montoMatch[2]) num *= 1000;
    monto = num;
  }
  for (const [cat, keywords] of Object.entries(categorias)) {
    if (keywords.some(k => new RegExp(`\\b${k.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')}\\b`, 'i').test(lower))) { categoria = cat; break; }
  }
  descripcion = rawText;
  if (!monto || !categoria) {
    estado = 'Revisar';
    motivo = (!monto && !categoria) ? 'No se detectó monto ni categoría'
             : (!monto ? 'No se detectó un monto claro' : 'No se detectó una categoría reconocida');
    categoria = categoria || 'Varios';
    monto = monto || 0;
  }
}

return {
  json: {
    ...$json,
    ignorar: false,
    categoria,
    monto,
    descripcion,
    estado,
    motivo_revision: motivo
  }
};
